import { BodyPartCode, BodyPartGroupCode, BODY_PART_GROUP_CHILDREN } from '@second-body/shared'

export type BodyGroupCode = Exclude<BodyPartGroupCode, 'body'>

// 전체뷰 viewBox 사각형 (FIGMA_VIEW_BOX 파싱)
export const FULL_RECT = { x: 230, y: 100, w: 545, h: 1050 }
// 표시 박스 세로/가로 비율 (전체뷰 기준 고정)
export const DISPLAY_ASPECT_HW = FULL_RECT.h / FULL_RECT.w
// flip 축(x=502.5) 기준 미러 → 표시좌표 = 1005 - 원본x
const FLIP_X2 = 1005

export type BodyView = 'front' | 'back'

// 앞면 전용(뒷면엔 없음) / 뒷면 전용 / 나머지는 both
const FRONT_ONLY = new Set<BodyPartCode>([
  'left_eye',
  'right_eye',
  'nose',
  'mouth',
  'left_ear',
  'right_ear',
  'skin_face',
  'chest',
  'abdomen',
  'pelvis',
  'genitalia',
])
const BACK_ONLY = new Set<BodyPartCode>(['back', 'lower_back'])

export function partView(code: BodyPartCode): 'front' | 'back' | 'both' {
  if (FRONT_ONLY.has(code)) return 'front'
  if (BACK_ONLY.has(code)) return 'back'
  return 'both'
}
export function isVisibleOn(code: BodyPartCode, view: BodyView): boolean {
  const v = partView(code)
  return v === 'both' || v === view
}

